import re

maps_file = open('/proc/1/maps', 'r')
mem_file = open('/proc/1/mem', 'rb', 0)

# Look for THESISKEY{ followed by hex chars (actual formatted token)
# Also look for the context around THESISKEY{%s}

for line in maps_file:
    m = re.match(r'([0-9a-f]+)-([0-9a-f]+) ([rwxp-]+)', line)
    if not m:
        continue
    start = int(m.group(1), 16)
    end = int(m.group(2), 16)
    perms = m.group(3)

    if 'r' not in perms:
        continue
    size = end - start
    if size > 50*1024*1024:
        continue

    try:
        mem_file.seek(start)
        data = mem_file.read(size)

        # Find all occurrences of THESISKEY{
        pos = 0
        while True:
            idx = data.find(b'THESISKEY{', pos)
            if idx == -1:
                break
            snippet = data[idx:idx+200]
            # Check if the content after { looks like an actual hash (hex chars)
            after_brace = snippet[10:]
            if after_brace and after_brace[0:1] not in [b'%', b'.', b' ', b'\\\\']:
                first_char = chr(after_brace[0])
                if first_char not in ['%', '.', ' ', chr(92)]:
                    print(f'Candidate at {hex(start+idx)}: {snippet[:120]}')
            pos = idx + 1
    except Exception as e:
        pass

maps_file.close()
mem_file.close()
print('Done')
